#' Automatic reporting of GHR model selection functions.
#'
#' Generates reports of the semi-automatic model selection carried
#' out by [select_re] or [select_fe]. It requires `rmarkdown` to be
#' run.
#'
#' @param select_out A GHRselect_re generated by [select_re] or a
#' GHRselect_fe object generated by [select_fe].
#' @param output_file A character indicating the output file.
#' @param quiet Logical; if \code{TRUE} (default), suppresses the knitting
#' progress and pandoc command printed by \code{rmarkdown::render()}.
#'
#' @return Silent output path where the html report is saved.
#'
#' @seealso [select_re], [select_fe]
#'
#' @examples
#' \dontrun{
#' # Read data
#' library(sf)
#' data(dengue_MS)
#' dengue_MS <- dengue_MS[complete.cases(dengue_MS), ]
#'
#' # Compute graph
#' data(map_MS)
#' nb <- spdep::poly2nb(map_MS)
#' g <- spdep::nb2mat(nb, style = "B")
#'
#' # Prepare indices
#' dengue_MS$spatial_id <- as.numeric(as.factor(dengue_MS$micro_code))
#' dengue_MS$seasonal_id <- dengue_MS$month
#' dengue_MS$year_id <- dengue_MS$year
#'
#' # Prepare precision priors
#' prec1 <- list(prec = list(prior = "pc.prec", param = c(0.5, 0.01)))
#' prec2 <- list(prec = list(prior = "pc.prec", param = c(0.25, 0.01)))
#'
#' # Run RE model selection
#' dengue_re <- select_re(
#'   data = dengue_MS,
#'   outcome = "dengue_cases",
#'   prior = c("prec1", "prec2"),
#'   offset_var = "pop100000",
#'   time = "date",
#'   unit = "micro_name"
#' )
#'
#' # Generate report
#' select_report(dengue_re, file.path(tempdir(), "random_effects.html"))
#' }
#'
#' @export
select_report <- function(
  select_out,
  output_file,
  quiet = TRUE
) {
  # Dependency checks
  rlang::check_installed(
    "rmarkdown",
    reason = "to render the report with `select_report()`."
  )
  if (!rmarkdown::pandoc_available()) {
    stop(
      "Pandoc is required to render the report but was not found. ",
      "See `rmarkdown::pandoc_available()` for details."
    )
  }

  # Output file checks
  if (!is.character(output_file) || length(output_file) != 1) {
    stop("'output_file' must be a single character string.")
  }
  if (!grepl("\\.html$", output_file)) {
    stop("Output file must have .html extension")
  }

  # File name and dir
  output_dir <- dirname(output_file)
  output_name <- basename(output_file)

  # Report type
  if (inherits(select_out, "GHRselect_re")) {
    template <- "select_re.Rmd"
  } else if (inherits(select_out, "GHRselect_fe")) {
    template <- "select_fe.Rmd"
  } else {
    stop(
      "The report can only be built from objects from the functions ",
      "'select_re' and 'select_fe'"
    )
  }

  # Render from a temporary copy of the template: rmarkdown writes its
  # intermediate files next to the input, and the installed package directory
  # may be read-only
  template_path <- system.file(
    file.path("templates", template),
    package = "GHRmodel"
  )
  if (!nzchar(template_path)) {
    stop(
      "Report template '",
      template,
      "' could not be found in the ",
      "installed GHRmodel package."
    )
  }
  tmp_dir <- tempfile("select_report_")
  dir.create(tmp_dir)
  on.exit(unlink(tmp_dir, recursive = TRUE), add = TRUE)
  tmp_template <- file.path(tmp_dir, template)
  if (!file.copy(template_path, tmp_template)) {
    stop("The report template could not be copied to a temporary directory.")
  }

  rmarkdown::render(
    tmp_template,
    output_file = output_name,
    output_dir = output_dir,
    output_format = "html_document",
    params = list(results = select_out),
    envir = new.env(parent = asNamespace("GHRmodel")),
    quiet = quiet
  )
}
